import { Component, EventEmitter, Input, Output } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Curso } from '../../models/curso.model';

@Component({
  selector: 'app-curso-list',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './curso-list.component.html',
  styleUrl: './curso-list.component.css',
})
export class CursoListComponent {
  @Input() cursos: Curso[] = [];
  @Input() cargando = false;
  @Output() editar = new EventEmitter<Curso>();
  @Output() eliminar = new EventEmitter<string>();

  onEditar(curso: Curso): void {
    this.editar.emit(curso);
  }

  onEliminar(curso: Curso): void {
    if (curso._id && confirm(`¿Eliminar el curso "${curso.nombre}"?`)) {
      this.eliminar.emit(curso._id);
    }
  }
}
<div class="tarjeta">
  <h2>Cursos registrados</h2>

  <p *ngIf="cargando">Cargando cursos...</p>

  <table *ngIf="!cargando && cursos.length > 0">
    <thead>
      <tr>
        <th>Nombre</th>
        <th>Instructor</th>
        <th>Categoría</th>
        <th>Duración</th>
        <th>Precio</th>
        <th>Acciones</th>
      </tr>
    </thead>
    <tbody>
      <tr *ngFor="let curso of cursos">
        <td>
          <strong>{{ curso.nombre }}</strong>
          <div class="descripcion">{{ curso.descripcion }}</div>
        </td>
        <td>{{ curso.instructor }}</td>
        <td>{{ curso.categoria }}</td>
        <td>{{ curso.duracionHoras }} h</td>
        <td>S/ {{ curso.precio }}</td>
        <td class="acciones-celda">
          <button class="btn btn-editar" (click)="onEditar(curso)">Editar</button>
          <button class="btn btn-eliminar" (click)="onEliminar(curso)">Eliminar</button>
        </td>
      </tr>
    </tbody>
  </table>

  <p *ngIf="!cargando && cursos.length === 0" class="vacio">
    Aún no hay cursos registrados. Usa el formulario de arriba para crear el primero.
  </p>
</div>
